            "state": to_state,
            "record": record_copy,
            "audits": list(audits),
            "notifies": list(notifies),
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
